mapper.select:
SELECT d.diary_no, d.diary_name, sc.sub_cd_nm AS diary_type, d.diary_content, d.achievement, s.student_name, s.student_class_no FROM diary d LEFT JOIN student_manage s ON d.student_no = s.student_no LEFT JOIN sub_cd sc ON d.diary_type = sc.sub_cd WHERE s.student_no = #{studentNo}
AND TO_NUMBER(TO_CHAR(d.diary_name,'MM')) = ${month}
ORDER BY d.diary_name DESC

mapper.insert:

	SELECT NVL(MAX(diary_no), 0) + 1
	FROM diary

INSERT into diary(
student_no
,diary_no
,diary_name
,diary_type
,diary_content
,achievement
)
VALUES(
#{studentNo}
,#{diaryNo}
,#{diaryName}
,#{diaryType}
,#{diaryContent}
,#{ach}
)
